struct Value {bool present=false;DWORD type=0;Bytes data;bool operator==(const Value&)const=default;};
inline Value get(HKEY key,const wchar_t* name){Value v;DWORD bytes=0;auto e=RegQueryValueExW(key,name,nullptr,&v.type,nullptr,&bytes);if(e==ERROR_FILE_NOT_FOUND)return v;check(e==0&&bytes<=65536,e?e:ERROR_INVALID_DATA);v.data.resize(bytes);e=RegQueryValueExW(key,name,nullptr,&v.type,v.data.data(),&bytes);check(e==0,e);v.data.resize(bytes);v.present=true;return v;}
