inline std::wstring string(const Value& v){check(v.present&&v.type==REG_SZ&&v.data.size()>=2&&v.data.size()%2==0,ERROR_INVALID_OWNER);auto text=(const wchar_t*)v.data.data();check(text[v.data.size()/2-1]==0,ERROR_INVALID_OWNER);return text;}
inline bool equal(const Value& a,const Value& b){return a.present==b.present&&a.type==b.type&&a.data==b.data;}
inline std::map<std::wstring,Value> values(HKEY key){DWORD children=0,count=0;check(RegQueryInfoKeyW(key,nullptr,nullptr,nullptr,&children,nullptr,nullptr,&count,nullptr,nullptr,nullptr,nullptr)==0);check(children==0&&count<64,ERROR_INVALID_OWNER);std::map<std::wstring,Value> result;for(DWORD i=0;i<count;i++){wchar_t name[256]={};DWORD length=256;check(RegEnumValueW(key,i,name,&length,nullptr,nullptr,nullptr,nullptr)==0);result[name]=get(key,name);}return result;}
inline std::wstring canonical(const std::wstring& path){check(path.size()>3&&path[1]==L':'&&path[2]==L'\\'&&path.find_first_of(L"*?\r\n\"")==std::wstring::npos,ERROR_INVALID_OWNER);wchar_t full[32768]={};auto n=GetFullPathNameW(path.c_str(),32768,full,nullptr);check(n&&n<32768,ERROR_INVALID_OWNER);check(same(path,full),ERROR_INVALID_OWNER);return full;}
inline bool contains(const Bytes& data,const wchar_t* text){auto first=(const BYTE*)text;return std::search(data.begin(),data.end(),first,first+wcslen(text)*2)!=data.end();}
inline bool islandBinary(const std::wstring& path){auto bytes=read(path);if(bytes.size()<256||bytes[0]!='M'||bytes[1]!='Z')return false;DWORD offset=0;memcpy(&offset,bytes.data()+60,4);if(offset>bytes.size()-24||memcmp(bytes.data()+offset,"PE\0\0",4))return false;return contains(bytes,L"OwnIsland.Surface")||contains(bytes,L"OwnIsland.Health.");}
