inline std::wstring commandRoot(const std::wstring& command){int count=0;auto args=CommandLineToArgvW(command.c_str(),&count);check(args&&count>0,ERROR_INVALID_OWNER);std::wstring path=args[0];bool valid=true;for(int i=1;i<count;i++)valid&=!wcscmp(args[i],L"--silent")||!wcscmp(args[i],L"--logon");LocalFree(args);check(valid,ERROR_INVALID_OWNER);return archiveRoot(path);}
