    const std::vector<std::wstring> allowed={L"Island.exe",L"Island.Desktop.exe",L"Island.Files.exe",L"Island.Start.exe",L"Island.Setup.exe",L"Island.Preload.exe",L"Island.Preload.Install.exe",L"Island.SettingsHandler.dll",L"installed.ini",L"transaction.ini",L"setup.log",L"setup.log.previous",L"recovery",L"README.md",L"README.txt",L"LICENSE",L"LICENSE.txt",L"THIRD_PARTY_NOTICES",L"Install-EarlyStartup.cmd",L"Remove-EarlyStartup.cmd",L"Uninstall-Island.cmd",L"Remove-Island-Service.cmd",L"Restore-Explorer.cmd",L"Restore-Settings.cmd"};
